import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_perfect_cube(n):
    if n < 0:
        return None
    if n == 0:
        return 0
    # Use floating point cube root and round to nearest integer
    root = round(n**(1/3))
    if root * root * root == n:
        return int(root)
    return None

# Generate primes up to 200
primes = []
for num in range(2, 201):
    if is_prime(num):
        primes.append(num)

# Filter primes q such that q = 1 (mod 3)
# Based on W2's finding that p != 3, which implies q = 1 (mod 3)
q_candidates = [q for q in primes if q % 3 == 1]

print(f"Primes q <= 200 such that q = 1 (mod 3): {q_candidates}")
print("-" * 30)

findings = []
for q in q_candidates:
    N = q**2 - q + 1
    p = is_perfect_cube(N)

    if p is not None:
        # N is a perfect cube p^3
        if p > 1 and is_prime(p) and p != q:
            findings.append((q, p, N))
        # Edge case check: p=1 implies N=1, which means q^2-q=0, q=1 (not prime) or q=0 (not prime). So p>1 if q is prime.

# Special check for q=19 (already known solution)
# q=19: N = 361 - 19 + 1 = 343 = 7^3. p=7. p != q. This should be found.

print("--- Findings (q, p, N) ---")
if not findings:
    print("No solutions found for q up to 200 satisfying the criteria.")
else:
    for q, p, N in findings:
        print(f"Found solution: q={q}, p={p}. N = {N} = {p}^3. Condition p != q satisfied.")

# Check some non-q=1 (mod 3) primes just in case, although W2 said to focus on this.
# Primes q=2, 5, 11, 17, ... (q = 2 mod 3)
q_candidates_2mod3 = [q for q in primes if q % 3 == 2]
print("\n--- Testing primes q = 2 (mod 3) (Extra check) ---")
for q in q_candidates_2mod3:
    N = q**2 - q + 1
    p = is_perfect_cube(N)
    if p is not None:
        # If p is prime and p!=q, we have a solution.
        if p > 1 and is_prime(p) and p != q:
            print(f"Found solution (unexpected): q={q}, p={p}. N = {N} = {p}^3.")

